import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';
import {initializeTestEnvironment,assertFails} from '@firebase/rules-unit-testing';
import {doc,setDoc,getDoc} from 'firebase/firestore';
import {initializeApp,deleteApp} from 'firebase-admin/app';import {getFirestore,Timestamp,GeoPoint} from 'firebase-admin/firestore';
import {fixtureSnapshot} from './migration-test-fixture.mjs';import {sourceFromDocuments,readDocuments,hash,same,encode,decode} from '../../scripts/migration-io.mjs';import {rehearse} from '../../scripts/migration-rehearsal.mjs';import {planDocuments} from '../../scripts/migration-contract.mjs';import {executeMigration} from '../../scripts/migration-executor.mjs';
const host=process.env.FIRESTORE_EMULATOR_HOST,projectId='demo-gepuzzellig-migration-test';if(!/^(127\.0\.0\.1|localhost):\d+$/.test(host||''))throw Error('Migratiehersteltest vereist expliciete lokale emulator');
const app=initializeApp({projectId},'migration-recovery-test'),db=getFirestore(app);const types={Timestamp,GeoPoint,encode};const dir=fs.mkdtempSync(path.join(os.tmpdir(),'gp-emulator-'));let freezeEnv;
try{
 const clear=await fetch(`http://${host}/emulator/v1/projects/${projectId}/databases/(default)/documents`,{method:'DELETE'});assert(clear.ok);freezeEnv=await initializeTestEnvironment({projectId,firestore:{rules:fs.readFileSync('firestore.freeze.rules','utf8'),host:host.split(':')[0],port:Number(host.split(':')[1])}});const client=freezeEnv.authenticatedContext('test-client').firestore();await assertFails(setDoc(doc(client,'profiles','test-client'),{playerId:'new-client-write'}));await assertFails(getDoc(doc(client,'profiles','test-client')));
 const snapshot=fixtureSnapshot();snapshot.documents['safetyFixtures/missingParent/deep/typed']={when:encode(new Timestamp(100,123456000)),bytes:encode(Buffer.from('backup')),position:encode(new GeoPoint(52.1,4.3))};snapshot.documents['dailyPlans/p_owner/days/2026-10-26']={schemaVersion:4,playerId:'p_owner',date:'2026-10-26',favoritePuzzleTypes:['bin'],difficulties:{bin:'hard'},createdAt:100};snapshot.source=sourceFromDocuments(snapshot.documents);
 for(const [p,data]of Object.entries(snapshot.documents))await db.doc(p).set(decode(data,{...types,db}));assert.deepEqual(await readDocuments(db),snapshot.documents,'initial full backup including missing parents and Firestore types');
 const {target,report}=rehearse(JSON.stringify(snapshot));assert.deepEqual(report.checks.blockers,[]);for(let i=0;i<220;i++)target.progress.p_owner['extra'+i]={...Object.values(target.progress.p_owner)[0],puzzleKey:'free-'+i};
 const options={snapshot,documents:planDocuments(target),provenance:{sourceSha256:hash(snapshot),candidateSha256:hash(target),releaseCommit:report.releaseCommit},types,journalFile:path.join(dir,'partial.json')};
 await assert.rejects(executeMigration(db,{...options,afterCommit:async n=>{if(n===1)throw Error('interrupted apply')}}),/interrupted/);const directRollback=await executeMigration(db,{...options,rollback:true});assert(directRollback.baselineRestored,'partial apply can be restored directly');
 const next={...options,journalFile:path.join(dir,'resume.json')};await assert.rejects(executeMigration(db,{...next,afterCommit:async n=>{if(n===1)throw Error('lost local cursor')}}),/lost local cursor/);await executeMigration(db,next);const complete=await readDocuments(db);await executeMigration(db,next);assert(same(await readDocuments(db),complete),'same candidate can be safely repeated');assert(complete['dailyPlans/p_owner/days/2026-10-26']);
 await assert.rejects(executeMigration(db,{...next,rollback:true,afterCommit:async n=>{if(n===1)throw Error('interrupted rollback')}}),/interrupted rollback/);const restored=await executeMigration(db,{...next,rollback:true});assert(restored.baselineRestored);assert(same(await readDocuments(db),snapshot.documents),'all profiles, existing data and types restored; new paths removed');
 const conflict={...options,journalFile:path.join(dir,'conflict.json')};await executeMigration(db,conflict);await db.doc('profiles/auth-owner').update({displayName:'newer user data'});const newer=await readDocuments(db);await assert.rejects(executeMigration(db,{...conflict,rollback:true}),/afwijkende data/);assert(same(newer,await readDocuments(db)),'rollback preserves newer writes by stopping');
 console.log('OK: echte Firestore-emulator — gedeeltelijke apply, verloren journalcursor, herhalen, onderbroken rollback, exacte typed-datarecovery en stop bij nieuwere writes.');
}finally{if(freezeEnv)await freezeEnv.cleanup();await deleteApp(app)}
